#!/usr/bin/env python3
"""Missing .cryasset metadata, generated by the ENGINE'S OWN pipeline (ENGINE_LEARNING_PLAN A10), without opening the Asset Browser and without touching a single existing metadata file.

The manual's "Generating Metadata" (Asset System page) is the Asset Browser's Edit > Generate/Repair All Metadata; the launcher's project action `metagen` (Tools/CryVersionSelector/cryrun.py) runs the same
thing: `Tools/rc/rc.exe /job=Tools/cryassets/rcjob_cryassets.xml /src=<the project's assets>`. The job writes `<file>.cryasset` for every cgf, chr, skin, dds, mtl, cga, anm, cdf, caf, wav, ogg, cax, pfx ... it
finds, and it REPLACES existing metadata files with new ones (a new random GUID each time: the assets that refer to one by GUID would lose the link). So this module runs the very same job with
`/targetroot=<scratch folder>`: RC writes its answer there, and only the files that do not exist in the project are copied over (apply=True). Nothing is ever overwritten.

Measured on the Ashvale sample level: RC finished the whole project in 13 s and wrote 828 files; 457 already existed (they differ from the new ones only by the GUID), 371 were missing: 158 meshes, 129 textures, 58
ogg sounds, 26 materials. The `_lodN.cgf` files get none (the engine treats them as part of their mesh), and neither do .adb, .png thumbnails or .tif sources.

    python assets/asset_meta.py            # dry run: what would be created
    python assets/asset_meta.py --apply    # create the missing files
"""
import os as _os, sys as _sys
_sys.path.insert(0, _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__))))
import _paths  # noqa: F401,E402  (puts every tool folder on sys.path; _paths.ROOT is the repository root)
import hashlib
import os
import shutil
import subprocess
import sys
import tempfile
import time

HERE = _paths.ROOT
PROJECT = __import__("project_root").PROJECT
ASSETS = os.path.join(PROJECT, "Assets")
# Engine install folder: env CRYENGINE_ENGINE_DIR or CRYENGINE_ENGINE (asset_lint and preflight use the first name), default the Launcher's 5.7.1 LTS folder.
ENGINE = os.environ.get("CRYENGINE_ENGINE_DIR") or os.environ.get("CRYENGINE_ENGINE") or (os.path.expandvars(r"%LOCALAPPDATA%\Programs\CRYENGINE Launcher\Engines\crytek\cryengine-57-lts\5.7.1"))
RC = os.path.join(ENGINE, "Tools", "rc", "rc.exe")
JOB = os.path.join(ENGINE, "Tools", "cryassets", "rcjob_cryassets.xml")
SCRATCH_ROOT = os.path.join(HERE, "engine_data", "cryasset_scratch")
TIMEOUT = 600


class MetaError(RuntimeError):
    pass


def _sha(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        h.update(f.read())
    return h.hexdigest()


def run_rc(assets_dir, target_root, rc=RC, job=JOB, timeout=TIMEOUT):
    """The engine's job into target_root -> (exit code, seconds). The command is fixed: nothing from the caller is passed to a shell."""
    for p, what in ((rc, "the resource compiler"), (job, "the cryassets job")):
        if not os.path.isfile(p):
            raise MetaError("%s is not at %s" % (what, p))
    os.makedirs(target_root, exist_ok=True)
    t0 = time.time()
    try:
        proc = subprocess.run([rc, "/job=" + job, "/src=" + assets_dir, "/targetroot=" + target_root, "/verbose=0"], stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                              cwd=os.path.dirname(rc), timeout=timeout, check=False)
    except subprocess.TimeoutExpired as exc:
        raise MetaError("the resource compiler did not finish in %d s" % timeout) from exc
    return proc.returncode, time.time() - t0


def plan(assets_dir=ASSETS, target_root=None):
    """Compare RC's output with the project -> {new: [rel], existing: [rel], source_missing: [rel]}"""
    new, existing, orphan = [], [], []
    for root, _dirs, files in os.walk(target_root):
        for name in files:
            if not name.lower().endswith(".cryasset"):
                continue
            rel = os.path.relpath(os.path.join(root, name), target_root)
            dst = os.path.join(assets_dir, rel)
            if os.path.exists(dst):
                existing.append(rel)
            elif not os.path.isfile(dst[:-len(".cryasset")]):
                orphan.append(rel)
            else:
                new.append(rel)
    return {"new": sorted(new), "existing": sorted(existing), "source_missing": sorted(orphan)}


def generate(apply=False, assets_dir=ASSETS, scratch_root=SCRATCH_ROOT, rc=RC, job=JOB, keep=False):
    """-> {applied, rc_exit, seconds, would_create | created, by_type, existing, examples}"""
    os.makedirs(scratch_root, exist_ok=True)
    target = tempfile.mkdtemp(prefix="run_", dir=scratch_root)
    try:
        code, seconds = run_rc(assets_dir, target, rc, job)
        if code != 0:
            raise MetaError("the resource compiler exited with %d" % code)
        p = plan(assets_dir, target)
        by_type = {}
        for rel in p["new"]:
            ext = os.path.splitext(rel[:-len(".cryasset")])[1].lower() or "(none)"
            by_type[ext] = by_type.get(ext, 0) + 1
        created = []
        if apply:
            for rel in p["new"]:
                dst = os.path.join(assets_dir, rel)
                if os.path.exists(dst):                       # re-checked at the moment of the copy: never overwrite
                    continue
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copyfile(os.path.join(target, rel), dst)
                created.append(rel.replace(os.sep, "/"))
        return {"applied": bool(apply), "rc_exit": code, "seconds": round(seconds, 1), "rc_wrote": len(p["new"]) + len(p["existing"]) + len(p["source_missing"]),
                ("created" if apply else "would_create"): len(created) if apply else len(p["new"]), "by_type": by_type, "already_have_metadata": len(p["existing"]),
                "metadata_for_missing_source": len(p["source_missing"]), "examples": [r.replace(os.sep, "/") for r in (created if apply else p["new"])[:8]],
                "files": [r.replace(os.sep, "/") for r in (created if apply else p["new"])]}
    finally:
        if not keep:
            shutil.rmtree(target, ignore_errors=True)


def main():
    r = generate("--apply" in sys.argv)
    r.pop("files", None)
    for k, v in r.items():
        print("  %-26s %s" % (k, v))


if __name__ == "__main__":
    main()
